create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, callsign text not null default 'Pilot', faction text not null default 'AURORA', level int not null default 1, xp bigint not null default 0, credits bigint not null default 0, premium bigint not null default 0, created_at timestamptz default now());
create table if not exists public.player_state (user_id uuid primary key references auth.users(id) on delete cascade, map_id text not null default 'SOL-1', x double precision default 0, y double precision default 0, hp bigint default 10000, shield bigint default 8000, ship_id text default 'sparrow', updated_at timestamptz default now());
create table if not exists public.inventory (id bigint generated by default as identity primary key,user_id uuid references auth.users(id) on delete cascade,item_id text not null,quantity bigint not null default 1,slot text,created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.player_state enable row level security; alter table public.inventory enable row level security;
create policy "own profile" on public.profiles for all using (auth.uid()=id) with check (auth.uid()=id); create policy "own state" on public.player_state for all using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy "own inventory" on public.inventory for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
